REM INSERTING into MBASSQLDEF
Insert into MBASSQLDEF (SQL_ID,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME,SQL_ID_DESC_1,SQL_ID_DESC_2,SQL_ID_DESC_3,SQL_GROUP,SYS_SQL_FLAG,SQL_1,SQL_2,SQL_3,SQL_4,SQL_5) values ('VIEW_CARRIER_GROUP_BY_OPER','ADMIN','20120111161351','ADMIN','20120111163117','View Carrier Group List by Operation',' ',' ','RAS',' ','SELECT CGR.CRR_GROUP, CGR.CRR_GRP_DESC
FROM MRASCGRREL REL, MRASCRRGRP CGR
WHERE REL.FACTORY = $FACTORY 
    AND REL.OPER=$1
	AND REL.FACTORY = CGR.FACTORY
	AND REL.CRR_GROUP = CGR.CRR_GROUP
ORDER BY CGR.CRR_GROUP
',' ',' ',' ',' ');
Insert into MBASSQLDEF (SQL_ID,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME,SQL_ID_DESC_1,SQL_ID_DESC_2,SQL_ID_DESC_3,SQL_GROUP,SYS_SQL_FLAG,SQL_1,SQL_2,SQL_3,SQL_4,SQL_5) values ('VIEW_EMPTY_CARRIER','ADMIN','20110427092700','ADMIN','20120111163337','View empty carrier',' ',' ','RAS',' ','SELECT DEF.CRR_GROUP, DEF.CRR_ID 
FROM MRASCRRDEF DEF, MRASCGRREL REL
WHERE REL.OPER = $1
  AND DEF.CRR_GROUP LIKE $2
  AND REL.FACTORY = $FACTORY 
  AND REL.FACTORY = REL.FACTORY 
  AND REL.CRR_GROUP = DEF.CRR_GROUP 
  AND DEF.CRR_ID NOT IN (
    SELECT CRR_ID 
	FROM MWIPCRRLOT 
	WHERE FACTORY = $FACTORY
  ) 
ORDER BY DEF.CRR_GROUP, DEF.CRR_ID
',' ',' ',' ',' ');
Insert into MBASSQLDEF (SQL_ID,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME,SQL_ID_DESC_1,SQL_ID_DESC_2,SQL_ID_DESC_3,SQL_GROUP,SYS_SQL_FLAG,SQL_1,SQL_2,SQL_3,SQL_4,SQL_5) values ('VIEW_LOT_BY_MATERIAL','ADMIN','20120111164635',' ',' ','View Lot by Material',' ',' ','WIP',' ','SELECT * 
FROM MWIPLOTSTS 
WHERE FACTORY = $FACTORY 
  AND MAT_ID = $1 
  AND LOT_DEL_FLAG = '' ''
ORDER BY OPER, LOT_ID
',' ',' ',' ',' ');
Insert into MBASSQLDEF (SQL_ID,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME,SQL_ID_DESC_1,SQL_ID_DESC_2,SQL_ID_DESC_3,SQL_GROUP,SYS_SQL_FLAG,SQL_1,SQL_2,SQL_3,SQL_4,SQL_5) values ('VIEW_LOT_BY_RESOURCE','ADMIN','20110307182519','ADMIN','20120111173004','View Lot by Processed Resource',' ',' ','WIP',' ','SELECT RHS.TRAN_TIME, RHS.OPER, RHS.LOT_ID, RHS.QTY_1, LHS.START_RES_ID, LHS.START_TIME
FROM MRASRESLTH RHS, MWIPLOTHIS LHS
WHERE RHS.FACTORY = $FACTORY
  AND RHS.RES_ID = $1
  AND RHS.OPER LIKE $2
  AND RHS.RES_HIST_DEL_FLAG = '' ''
  AND RHS.EVENT_ID = ''END_LOT''
  AND RHS.LOT_HIST_DEL_FLAG = '' ''
  AND RHS.LOT_ID = LHS.LOT_ID
  AND RHS.LOT_HIST_SEQ = LHS.HIST_SEQ
ORDER BY RHS.TRAN_TIME
',' ',' ',' ',' ');
Insert into MBASSQLDEF (SQL_ID,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME,SQL_ID_DESC_1,SQL_ID_DESC_2,SQL_ID_DESC_3,SQL_GROUP,SYS_SQL_FLAG,SQL_1,SQL_2,SQL_3,SQL_4,SQL_5) values ('VIEW_LOT_COUNT_BY_OPER','ADMIN','20120111172656',' ',' ','View Lot Count by Operation',' ',' ','WIP',' ','SELECT LOT.OPER, OPR.OPER_DESC, COUNT(LOT.LOT_ID) LOT_COUNT 
FROM MWIPLOTSTS LOT, MWIPOPRDEF OPR
WHERE LOT.FACTORY = $FACTORY 
    AND LOT.LOT_DEL_FLAG = '' ''
    AND LOT.FACTORY = OPR.FACTORY
    AND LOT.OPER = OPR.OPER
GROUP BY LOT.OPER, OPR.OPER_DESC
ORDER BY LOT.OPER
',' ',' ',' ',' ');
Insert into MBASSQLDEF (SQL_ID,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME,SQL_ID_DESC_1,SQL_ID_DESC_2,SQL_ID_DESC_3,SQL_GROUP,SYS_SQL_FLAG,SQL_1,SQL_2,SQL_3,SQL_4,SQL_5) values ('VIEW_OPER_LIST_BY_MATERIAL','ADMIN','20120111172222','ADMIN','20120111172335','View Operation List by Material',' ',' ','WIP',' ','SELECT FLW.FLOW, FLW.FLOW_DESC, OPR.OPER, OPR.OPER_DESC, OPR.UNIT_1, OPR.LOSS_TBL
FROM MWIPMATFLW MFW, MWIPFLWOPR FOP, MWIPFLWDEF FLW, MWIPOPRDEF OPR
WHERE MFW.FACTORY = $FACTORY
  AND MFW.MAT_ID = $1
  AND MFW.MAT_VER = 1
  AND MFW.FACTORY = FOP.FACTORY
  AND MFW.FLOW = FOP.FLOW
  AND MFW.FACTORY = FLW.FACTORY
  AND MFW.FLOW = FLW.FLOW
  AND FOP.FACTORY = OPR.FACTORY
  AND FOP.OPER = OPR.OPER
ORDER BY MFW.FLOW_SEQ_NUM, FOP.SEQ_NUM
',' ',' ',' ',' ');

Insert into MBASSQLDEF (SQL_ID,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME,SQL_ID_DESC_1,SQL_ID_DESC_2,SQL_ID_DESC_3,SQL_GROUP,SYS_SQL_FLAG,SQL_1,SQL_2,SQL_3,SQL_4,SQL_5) values ('VIEW_USER_LIST_BY_SEC_GROUP','ADMIN','20120120113308','ADMIN','20120120113709','View User List by Security Group',' ',' ','SEC',' ','SELECT FACTORY, SEC_GRP_ID, USER_ID, USER_DESC, EMAIL_ID, EXPIRE_DATE, ENTER_DATE, RETIRE_DATE
FROM MSECUSRDEF
WHERE FACTORY = $FACTORY
AND SEC_GRP_ID = $1
ORDER BY USER_ID
',' ',' ',' ',' ');
Insert into MBASSQLDEF (SQL_ID,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME,SQL_ID_DESC_1,SQL_ID_DESC_2,SQL_ID_DESC_3,SQL_GROUP,SYS_SQL_FLAG,SQL_1,SQL_2,SQL_3,SQL_4,SQL_5) values ('VIEW_RES_HISTORY_BY_EVENT','ADMIN','20120120101135','ADMIN','20131008154718','View Resource History by Event',' ',' ','RAS',' ','SELECT RES_ID, HIST_SEQ, EVENT_ID, TRAN_TIME, SYS_TRAN_TIME, LOT_ID 
FROM MRASRESHIS
WHERE FACTORY = $FACTORY
AND RES_ID = $1
AND EVENT_ID LIKE $2
ORDER BY HIST_SEQ DESC',' ',' ',' ',' ');
Insert into MBASSQLDEF (SQL_ID,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME,SQL_ID_DESC_1,SQL_ID_DESC_2,SQL_ID_DESC_3,SQL_GROUP,SYS_SQL_FLAG,SQL_1,SQL_2,SQL_3,SQL_4,SQL_5) values ('VIEW_LOT_BY_LOT_GROUP','ADMIN','20120120132602','ADMIN','20131017112302','View Lot List by Lot Group',' ',' ','WIP',' ','SELECT * FROM MWIPLOTSTS 
WHERE lot_cmf_1 like decode($1,'''',''%'',$1)
and lot_cmf_2 like decode($2,'''',''%'',$2)
and lot_cmf_3 like decode($3,'''',''%'',$3)
and lot_cmf_4 like decode($4,'''',''%'',$4)
and lot_cmf_5 like decode($5,'''',''%'',$5)
and lot_cmf_6 like decode($6,'''',''%'',$6)
and lot_cmf_7 like decode($7,'''',''%'',$7)
and lot_cmf_8 like decode($8,'''',''%'',$8)
and lot_cmf_9 like decode($9,'''',''%'',$9)
and lot_cmf_10 like decode($10,'''',''%'',$10)
and lot_cmf_11 like decode($11,'''',''%'',$11)
and lot_cmf_12 like decode($12,'''',''%'',$12)
and lot_cmf_13 like decode($13,'''',''%'',$13)
and lot_cmf_14 like decode($14,'''',''%'',$14)
and lot_cmf_15 like decode($15,'''',''%'',$15)
and lot_cmf_16 like decode($16,'''',''%'',$16)',' ',' ',' ',' ');
Insert into MBASSQLDEF (SQL_ID,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME,SQL_ID_DESC_1,SQL_ID_DESC_2,SQL_ID_DESC_3,SQL_GROUP,SYS_SQL_FLAG,SQL_1,SQL_2,SQL_3,SQL_4,SQL_5) values ('VIEW_LONG_QUERY_RANK_BY_SIZE','ADMIN','20130708175332','ADMIN','20130708175404','View Long Query Rank by Size',' ',' ','SYS',' ','SELECT TRAN_TIME, SUBSTR(SERVICE_NAME, 31) AS DB_FUNCTION_NAME, AVG_SEC, TOTAL_SEC, TOTAL_COUNT FROM (
    SELECT TO_CHAR(TO_DATE(TRAN_TIME, ''YYYYMMDDHH24MISS''), ''YYYY/MM/DD HH24:MI'') TRAN_TIME,
           SERVICE_NAME, AVG_SEC, TOTAL_SEC, TOTAL_COUNT, ROW_NUMBER() OVER (PARTITION BY TRAN_TIME ORDER BY AVG_SEC DESC) ROW_NUM
    FROM (
        SELECT TRAN_TIME, SERVICE_NAME, TO_CHAR(ROUND(TOTAL_SEC / TOTAL_COUNT, 3), ''999990.999'') AS AVG_SEC, TOTAL_SEC, TOTAL_COUNT
        FROM (
            SELECT TRAN_TIME, SERVICE_NAME, TO_CHAR(SUM(TOTAL_CONSUME_SEC), ''999990.999'') AS TOTAL_SEC, SUM(SERVICE_COUNT) AS TOTAL_COUNT
            FROM MSVMPFMLOG 
            WHERE SERVICE_NAME LIKE ''SYS_LONG_QUERY_RANKING_SIZE%''
              AND TRAN_TIME >= $1||''000000'' 
              AND TRAN_TIME < $2||''000000'' 
            GROUP BY TRAN_TIME, SERVICE_NAME
        )
        ORDER BY TRAN_TIME DESC, AVG_SEC DESC, TOTAL_SEC DESC, TOTAL_COUNT DESC
    )
)
WHERE ROW_NUM <= 10
ORDER BY TRAN_TIME DESC, AVG_SEC DESC',' ',' ',' ',' ');
Insert into MBASSQLDEF (SQL_ID,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME,SQL_ID_DESC_1,SQL_ID_DESC_2,SQL_ID_DESC_3,SQL_GROUP,SYS_SQL_FLAG,SQL_1,SQL_2,SQL_3,SQL_4,SQL_5) values ('VIEW_LONG_QUERY_RANK_BY_TIME','ADMIN','20130708172112','ADMIN','20130925142457','View Long Query Rank by Time',' ',' ','SYS',' ','SELECT TRAN_TIME, SUBSTR(SERVICE_NAME, 31) AS DB_FUNCTION_NAME, AVG_SEC, TOTAL_SEC, TO_CHAR(TOTAL_COUNT, ''99999,999'') AS TOTAL_COUNT FROM (
    SELECT TO_CHAR(TO_DATE(TRAN_TIME, ''YYYYMMDDHH24MISS''), ''YYYY/MM/DD HH24:MI'') TRAN_TIME, 
           SERVICE_NAME, AVG_SEC, TOTAL_SEC, TOTAL_COUNT, ROW_NUMBER() OVER (PARTITION BY TRAN_TIME ORDER BY AVG_SEC DESC) ROW_NUM
    FROM (
        SELECT TRAN_TIME, SERVICE_NAME, ROUND(TOTAL_SEC / TOTAL_COUNT, 3) AS AVG_SEC, TOTAL_SEC, TOTAL_COUNT
        FROM (
            SELECT TRAN_TIME, SERVICE_NAME, SUM(TOTAL_CONSUME_SEC) AS TOTAL_SEC, SUM(SERVICE_COUNT) AS TOTAL_COUNT
            FROM MSVMPFMLOG 
            WHERE SERVICE_NAME LIKE ''SYS_LONG_QUERY_RANKING_TIME%''
               AND TRAN_TIME >= $1||''000000'' 
               AND TRAN_TIME < $2||''000000'' 
            GROUP BY TRAN_TIME, SERVICE_NAME
        )
        ORDER BY TRAN_TIME DESC, AVG_SEC DESC, TOTAL_SEC DESC, TOTAL_COUNT DESC
    )
)
WHERE ROW_NUM <= 10
ORDER BY TRAN_TIME DESC, AVG_SEC DESC',' ',' ',' ',' ');
Insert into MBASSQLDEF (SQL_ID,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME,SQL_ID_DESC_1,SQL_ID_DESC_2,SQL_ID_DESC_3,SQL_GROUP,SYS_SQL_FLAG,SQL_1,SQL_2,SQL_3,SQL_4,SQL_5) values ('@VIEW_LONG_QUERY_RANK_BY_TIME','ADMIN','20130708172612','ADMIN','20130925135557','View Long Query Rank by Time',' ',' ','SYS',' ','SELECT ''TRAN_TIME`DB_FUNCTION_NAME`AVG_SEC`TOTAL_SEC`TOTAL_COUNT'' FROM DUAL
UNION ALL
SELECT * FROM (
    SELECT TRAN_TIME||''`''||SUBSTR(SERVICE_NAME, 31)||''`''||AVG_SEC||''`''||TOTAL_SEC||''`''||TOTAL_COUNT FROM (
        SELECT TO_CHAR(TO_DATE(TRAN_TIME, ''YYYYMMDDHH24MISS''), ''YYYY/MM/DD HH24:MI'') TRAN_TIME, 
               SERVICE_NAME, AVG_SEC, TOTAL_SEC, TOTAL_COUNT, ROW_NUMBER() OVER (PARTITION BY TRAN_TIME ORDER BY AVG_SEC DESC) ROW_NUM
        FROM (
            SELECT TRAN_TIME, SERVICE_NAME, TO_CHAR(ROUND(TOTAL_SEC / TOTAL_COUNT, 3), ''999990.999'') AS AVG_SEC, TOTAL_SEC, TOTAL_COUNT
            FROM (
                SELECT TRAN_TIME, SERVICE_NAME, TO_CHAR(SUM(TOTAL_CONSUME_SEC), ''999990.999'') AS TOTAL_SEC, SUM(SERVICE_COUNT) AS TOTAL_COUNT
                FROM MSVMPFMLOG 
                WHERE SERVICE_NAME LIKE ''SYS_LONG_QUERY_RANKING_TIME%''
                   AND TRAN_TIME >= $1||''000000'' 
                   AND TRAN_TIME < $2||''000000'' 
                GROUP BY TRAN_TIME, SERVICE_NAME
            )
            ORDER BY TRAN_TIME DESC, AVG_SEC DESC, TOTAL_SEC DESC, TOTAL_COUNT DESC
        )
    )
    WHERE ROW_NUM <= 10
    ORDER BY TRAN_TIME DESC, AVG_SEC DESC
)',' ',' ',' ',' ');
Insert into MBASSQLDEF (SQL_ID,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME,SQL_ID_DESC_1,SQL_ID_DESC_2,SQL_ID_DESC_3,SQL_GROUP,SYS_SQL_FLAG,SQL_1,SQL_2,SQL_3,SQL_4,SQL_5) values ('VIEW_PERFORMANCE_BY_TOTSVC','ADMIN','20130708170907','ADMIN','20130709164938','View Performance by Total Service',' ',' ','SYS',' ','SELECT TO_CHAR(TO_DATE(TRAN_TIME, ''YYYYMMDDHH24MISS''), ''YYYY/MM/DD HH24:MI'') TRAN_TIME, 
       TO_CHAR(ROUND(SUM(TOTAL_CONSUME_SEC) / SUM(SERVICE_COUNT), 3), ''999990.999'') AS AVG_SEC, 
       TO_CHAR(SUM(TOTAL_CONSUME_SEC), ''999990.999'') AS TOTAL_CONSUME_SEC, 
       TO_CHAR(SUM(CONSUME_SEC_1), ''999990.999'') AS DB_TIME, 
       TO_CHAR(SUM(TOTAL_CONSUME_SEC) - SUM(CONSUME_SEC_1), ''999990.999'') AS LOGIC_TIME, 
       TO_CHAR(ROUND((SUM(CONSUME_SEC_1) / SUM(TOTAL_CONSUME_SEC)) * 100, 2), ''999990.999'') AS DB_TIME_RATE, 
       SUM(SERVICE_COUNT) AS SERVICE_COUNT 
FROM MSVMPFMLOG 
WHERE SERVICE_NAME NOT LIKE ''SYS_LONG_QUERY_RANKING%'' 
AND SERVICE_NAME <> ''SYS_TABLE_SPACE_INCREASE_INFO'' 
AND TRAN_TIME >= $1||''000000'' 
AND TRAN_TIME < $2||''000000'' 
GROUP BY TRAN_TIME 
ORDER BY TRAN_TIME DESC, AVG_SEC DESC',' ',' ',' ',' ');
Insert into MBASSQLDEF (SQL_ID,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME,SQL_ID_DESC_1,SQL_ID_DESC_2,SQL_ID_DESC_3,SQL_GROUP,SYS_SQL_FLAG,SQL_1,SQL_2,SQL_3,SQL_4,SQL_5) values ('VIEW_PERFORMANCE_BY_SERVICE','ADMIN','20130708170745','ADMIN','20130826170029','View Performance by Service',' ',' ','SYS',' ','SELECT TO_CHAR(TO_DATE(TRAN_TIME, ''YYYYMMDDHH24MISS''), ''YYYY/MM/DD HH24:MI'') TRAN_TIME, 
       SERVICE_NAME, 
       TO_CHAR(ROUND(SUM(TOTAL_CONSUME_SEC) / SUM(SERVICE_COUNT), 3), ''999990.999'') AS AVG_SEC, 
       TO_CHAR(SUM(TOTAL_CONSUME_SEC), ''999990.999'') AS TOTAL_CONSUME_SEC, 
       SUM(CONSUME_SEC_1) AS DB_TIME, 
       SUM(TOTAL_CONSUME_SEC) - SUM(CONSUME_SEC_1) AS LOGIC_TIME, 
       ROUND((SUM(CONSUME_SEC_1) / SUM(TOTAL_CONSUME_SEC)) * 100, 2) AS DB_TIME_RATE, 
       SUM(SERVICE_COUNT) AS SERVICE_COUNT 
FROM MSVMPFMLOG 
WHERE SERVICE_NAME NOT LIKE ''SYS_LONG_QUERY_RANKING%'' 
AND SERVICE_NAME <> ''SYS_TABLE_SPACE_INCREASE_INFO'' 
AND TRAN_TIME >= $1||''000000'' 
AND TRAN_TIME < $2||''000000'' 
GROUP BY TRAN_TIME, SERVICE_NAME 
ORDER BY TRAN_TIME DESC, AVG_SEC DESC',' ',' ',' ',' ');
